import sys
import json
import pandas as pd
import numpy as np

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(to_float(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(to_float(total_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": round(to_float(total_rev_ly), 2),
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(to_float(total_units_tw), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(to_float(total_units_lw), 2),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(to_float(total_orders_tw), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(to_float(total_orders_lw), 2),
        "formula": "sum(Orders_LW)"
    })

    if pd.notna(total_rev_lw) and total_rev_lw != 0:
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(to_float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if pd.notna(total_rev_ly) and total_rev_ly != 0:
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(to_float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---------- TOP 3 ENTITIES BY REVENUE_TW ----------
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(3)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": round(to_float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": round(to_float(row['Share_Pct']), 1),
                "formula": "Revenue_TW / sum(Revenue_TW) * 100"
            })

    # ---------- TOP 3 WoW GAINERS / DECLINERS ----------
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    top_wow_gainers = wow_df.head(3)
    top_wow_decliners = wow_df.tail(3).sort_values('WoW_Pct')

    for _, row in top_wow_gainers.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(to_float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    for _, row in top_wow_decliners.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(to_float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- TOP 2 YoY GAINERS / DECLINERS ----------
    yoy_df = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=False)
    top_yoy_gainers = yoy_df.head(2)
    top_yoy_decliners = yoy_df.tail(2).sort_values('YoY_Pct')

    for _, row in top_yoy_gainers.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(to_float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    for _, row in top_yoy_decliners.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(to_float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Limit to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
